"""A0-only dimensioned CAD projections and cut sections; nominal review sheets."""
import html
import math
import re
import textwrap


def drawings(design, parts, instances):
    import cadquery as cq
    c=design['fabrication_geometry']['cartridge'];f=design['fabrication_geometry'];q=f['four_bar'];d=f['dummy_member']
    e=html.escape
    def project(part,view,x,y,label):
        shape=part.val() if hasattr(part,'val') else part
        if view=='XZ':shape=shape.rotate((0,0,0),(1,0,0),-90)
        elif view=='YZ':shape=shape.rotate((0,0,0),(0,0,1),-90).rotate((0,0,0),(1,0,0),-90)
        b=shape.BoundingBox();scale=min(440/max(b.xlen,1),255/max(b.ylen,1))
        # Request fitted width; no perspective or decorative reinterpretation.
        svg=cq.exporters.getSVG(shape,{'width':b.xlen*scale+60,'height':None,'marginLeft':30,'marginTop':25,'projectionDir':(0,0,1),'showAxes':False,'showHidden':True,'strokeWidth':1.1/scale})
        svg=re.sub(r'<\?xml[^>]*>','',svg);svg=re.sub(r'<!DOCTYPE[^>]*>','',svg)
        svg=f'<g transform="translate({x},{y+30})">'+svg+'</g>'
        left=x+30;right=left+b.xlen*scale;top=y+55;bottom=top+b.ylen*scale
        body=f'<text x="{x+20}" y="{y+15}" class="label">{e(label)}</text>'+svg
        # Extension lines meet the exact HLR-projected bounding limits.
        body+=f'<g class="dim"><path d="M{left},{bottom+4} V{bottom+32} M{right},{bottom+4} V{bottom+32}"/><path d="M{left},{bottom+24} H{right}" marker-start="url(#arr)" marker-end="url(#arr)"/></g>'
        body+=f'<text x="{(left+right)/2}" y="{bottom+46}" class="dimension">{b.xlen:.3f} {view[0]}</text>'
        body+=f'<g class="dim"><path d="M{right+4},{top} H{right+25} M{right+4},{bottom} H{right+25}"/><path d="M{right+20},{top} V{bottom}" marker-start="url(#arr)" marker-end="url(#arr)"/></g>'
        body+=f'<text x="{right+27}" y="{(top+bottom)/2}" class="small">{b.ylen:.3f} {view[1]}</text>'
        return body
    def section(part,plane):
        return cq.Workplane(plane).newObject([part.val()]).section().val()
    def sheet(n,title,views,notes):
        out=f'<svg xmlns="http://www.w3.org/2000/svg" width="1600" height="1132" viewBox="0 0 1600 1132"><defs><marker id="arr" viewBox="0 0 10 10" refX="5" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M0,0 L10,5 L0,10 z" fill="#37556e"/></marker></defs><style>text{{font-family:DejaVu Sans,sans-serif;fill:#182d3d}} .label{{font-size:17px;font-weight:bold}} .small{{font-size:13px}} .dimension{{font-size:14px;text-anchor:middle}} .dim{{stroke:#37556e;fill:none;stroke-width:1}} .note{{font-size:16px}}</style><rect width="1600" height="1132" fill="white"/><rect x="16" y="16" width="1568" height="1100" fill="none" stroke="#182d3d"/><text x="40" y="53" font-size="25">A0-D{n:03d}-R2 | {e(title)}</text><text x="40" y="84" font-size="16">ENGINEERING / SHOP REVIEW — NOT FABRICATION RELEASED — mm — DO NOT SCALE</text><path d="M30 100 H1570 M1100 120 V1040 M30 1055 H1570" stroke="#182d3d" fill="none"/>'
        for index,(part,view,label) in enumerate(views):out+=project(part,view,40+(index%2)*520,140+(index//2)*425,label)
        line=0
        for note in notes:
            for t in textwrap.wrap(note,46,break_long_words=False,break_on_hyphens=False):
                out+=f'<text x="1120" y="{151+line*23}" class="note">{e(t)}</text>';line+=1
            line+=.35
        if line>38:raise ValueError(f'drawing notes overflow: D{n}: {line}')
        out+='<text x="40" y="1081" font-size="14">General candidate limits: machined ±0.10; profile ±0.25; explicit fits/coordinates override. Threads 6H candidate.</text><text x="40" y="1104" font-size="14">Edge break 0.2–0.5 except bearing abutments R≤0.4 / keys 0.2. Materials per BOM. Independent review and inspection required.</text></svg>\n'
        return out
    p=parts;result={}
    def add(n,title,views,notes):result[f'A0-D{n:03d}-R2-{title.lower().replace(" ","-")}.svg']=sheet(n,title,views,notes)
    common=['Local part axes shown by dimension suffix; assembly locations in assembly_instances.json.','No tolerances or capacity inferred from mesh appearance.']
    add(1,'Fixture and roots',[(p['A0-101_fixture_base'],'XY','BASE / TOP'),(p['A0-101_fixture_base'],'XZ','BASE / FRONT'),(p['A0-109_root_standoff'],'XY','STANDOFF / TOP'),(p['A0-109_root_standoff'],'XZ','STANDOFF / FRONT')],[f"Base {f['fixture']['base_size_xyz']} A36; local center X=0 maps to global X=-130.",'Ø11 bench holes local (±120,±90). Ø10.5 roots (0,-60),(0,40).','Ø6 H7 tooling axis at local (130,0). Top face Z=0. Pattern ±0.25; flatness 0.30.',f"Standoff {f['fixture']['standoff_size_xyz']}; Ø10.5 through Z.",'Root rocker axes P/A remain global Z=35. Isolation and pivot washer stack require review.']+common)
    add(2,'Carriage and rocker',[(p['A0-103_carriage'],'XY','CARRIAGE / TOP'),(p['A0-103_carriage'],'XZ','CARRIAGE / FRONT'),(p['A0-102_rocker'],'XY','ROCKER / TOP'),(p['A0-102_rocker'],'XZ','ROCKER / FRONT')],[f"Carriage {q['carriage_size_xyz']}; center global (-185,-10,{q['carriage_center_z']}).",'Pivot Ø10.2 +0.10/0 at local (0,±50). Rocker Ø10.2 at (±27.5,0). Centers ±0.10; pattern TP Ø0.30.',f"Wide open relief to local X={q['carriage_relief_x_from_S']-20}, Y=±22; narrow lug relief to X={c['stop_lug_radius']+c['stop_lug_radius_tip']-22}, Y=±10.",f"Yoke M6 taps local X={ [x-20 for x in c['yoke_foot_holes_x']] }, Y=±54.",f"Carrier M6 taps local X={[x-20 for x in c['stop_carrier_foot_holes_x']]}, Y=±54.",'All M6 taps through 8; inspect screw tips clear rocker layer by ≥0.5. Pivot-head/washer stack remains supplier-open.']+common)
    add(3,'Dummy member',[(p['A0-108_dummy_member'],'XY','TUBE / TOP'),(p['A0-108_dummy_member'],'YZ','TUBE / END SECTION')],[f"Tube {d['outer']} square x {d['wall']} wall; 6061-T6.",f"Cut length {d['cut_length']} ±0.5. Straightness ≤0.75 / 300.",'Insertion 28 from -40 mouth to -12 socket bottom, relative S. Tube tip is X=-12; effective station remains 317 ±1.', 'Cut ends global (-217,-10,70), (-544,-10,70). Offsets 40/25; distal insertion 47.', 'Stock material section/lot and actual mass/CG require inspection.']+common)
    add(4,'Bearing yoke',[(p['A0-104_yoke_side'],'XZ','LOCATING YOKE / FRONT (MIRROR FOR LEFT)'),(p['A0-104_yoke_side'],'XY','YOKE / TOP'),(section(p['A0-114_floating_yoke'],'YZ'),'YZ','FLOATING YOKE SECTION A–A / X=0')],[f"6061-T6; plate {c['yoke_plate_size_xzy']} X/Z/Y. Local shaft axis X=Z=0.",f"Bottom Z={c['yoke_bottom_z_from_S']}; foot {c['yoke_foot_size_xyz']}, center Y={c['yoke_foot_center_y']}. Outboard toe X≤15 for Y≥8.",'Ø40.000..40.025 pockets: locating14 ±0.02; floating15 ±0.02 from +Y face. Ø35 through ledge; R≤0.4.',f"Foot Ø6.6 +0.10/0 at X={c['yoke_foot_holes_x']}, Y=24; access Ø20 at (20,20).",'3 x M4x0.7 taps, depth 7, R25 at 0/90/180° in XZ. Positional tolerance Ø0.20 to shaft axis.', 'Floating A0-114 at Y=20; locating A0-104 mirrored at -40. Feet Z=47. Assembled bore span60 ±0.20; check both float directions.', 'Supplier fit/internal clearance approval HOLD.']+common)
    add(5,'Bearing caps',[(p['A0-310_bearing_cap'],'XZ','LOCATING C CAP / FRONT'),(p['A0-310_bearing_cap'],'YZ','LOCATING CAP / SIDE'),(p['A0-311_floating_cap'],'YZ','FLOATING CAP / SIDE')],['6061-T6. Ø60 flange x4 ±0.02; Ø35.00..35.03 opening. Flat lower edge Z=-10 clears foot.',f"Nose OD39.80 ±0.03; locating length {c['bearing_cap_nose_length']} ±0.02; floating {c['bearing_float_cap_nose_length']} ±0.02.",'3 x Ø4.5 +0.10/0 through at R25, 0/90/180° XZ; pattern Ø0.20. M4x10 gives 6 nominal engagement.', 'C form retains the upper/side outer-ring arc. No nominal bearing crush. Cap stiffness, screws and axial float require independent review.', 'SKF housing abutment opening ≤35.8; project opening max35.03. Abutment R≤0.4.']+common)
    add(6,'Pitch shaft',[(p['A0-201_pitch_shaft'],'XY','SHAFT / KEY SIDE'),(p['A0-201_pitch_shaft'],'YZ','SHAFT / AXIAL VIEW'),(section(p['A0-201_pitch_shaft'],'YZ'),'YZ','SECTION A–A / X=0')],[f"4140 prehard; Ø17 h6 candidate 16.989..17.000; length {c['shaft_length']} ±0.03.",'Both ends M6x1 x16 deep; Ø5 tap-drill shown. Threads are callouts, no helical CAD geometry.',f"5.00 +0.025/0 key seats, depth 2.50 ±0.03: length30 at Y=0; length6 at Y={c['sector_center_y']+10}.",'Key seats stop before bearing journals. Seat ends square candidate; tool radius and key form must match.', 'End washer Ø21.6 x3, Ø6.6; M6x16 engagement13. Approved locking mandatory. Select shims for 0.05..0.15 end play.', 'h6 rotating-inner-ring fit/creep/CN clearance remains a release HOLD.']+common)
    add(7,'Output hub',[(p['A0-105_output_hub'],'XZ','HUB AND INTEGRAL LUG / FRONT'),(p['A0-105_output_hub'],'XY','HUB / TOP'),(section(p['A0-105_output_hub'],'XY'),'XY','SECTION A–A / Z=0'),(p['A0-105_output_hub'],'YZ','HUB / END')],[f"6061-T6 body {c['hub_size_xyz']}; body X=-40..20; widthY40 ±0.03; back corners bevel8.",'Ø17 shaft bore; 5.00 +0.025/0 key slot to Z=11. Bore/fit approval HOLD.',f"Socket {c['tube_socket_across_flats']} +0.15/0 square: OPEN -X mouth=-40; blind bottom=-12. Insertion=28.",'Split slot 1.5 along Y=0, Z≥0, X=-43..-10. Pinch axes +Y at X=-20,-32; Z=20. Near cheek Ø6.6; far M6x1.',f"Lug root half-height12 at X=15; taper to7.5 at X=45; tip arc R{c['stop_lug_radius_tip']} centered X={c['stop_lug_radius']}, Z=0; widthY={c['stop_lug_width']}.",f"Integral billet must cover finished X span {c['stop_lug_radius']+c['stop_lug_radius_tip']+40}, Y40, Z55; add shop allowance. Pinch/preload and tube-slip review open."]+common)
    add(8,'Index sector',[(p['A0-106_index_sector'],'XZ','SECTOR / FRONT'),(p['A0-106_index_sector'],'YZ','SECTOR / SIDE'),(p['A0-204_sector_key'],'XY','SECTOR KEY')],[f"Ø{c['sector_od']} x {c['sector_thickness']} 6061-T6; Ø17 bore; 5 mm key slot to Z=11.",f"Ø{c['index_hole_diameter']} +0.10/0 holes R{c['index_hole_radius']} at -30..90° each {c['index_increment_deg']}° in local XZ.",f"Assembly center global Y={c['sector_center_y']}; 5x5x6 key. Shaft key seat local Y={c['sector_center_y']+10}.",'Hole angular location ±0.10° candidate. Actual plunger support/nose/thread/engagement remains blocked.', 'Single-sided pin support; no double-shear or stop-impact credit.']+common)
    from PROJECTS.T56_CARBON.tools.a0_interfaces import stop_geometry
    contacts=stop_geometry(design);lo,hi=[r['backing_center_from_S_mm'] for r in contacts]
    add(9,'Stop carrier frame',[(p['A0-111_pitch_stop_carrier'],'XZ','RIGHT FRAME / PROFILE'),(p['A0-111_pitch_stop_carrier'],'XY','RIGHT FRAME / TOP'),(p['A0-111_pitch_stop_carrier'],'YZ','RIGHT FRAME / END')],[f"6061-T6 billet, web16 Y x22. Integral foot requires full drawn envelope, plus shop stock allowance. Profile node centers (X,Z), relative S:",f"({lo[0]:.5f},{lo[2]:.5f}) → ({lo[0]:.5f},80) → (82,80) → (82,-57) → (-20,-57) → ({hi[0]:.5f},{hi[2]:.5f}).",'Union centered 22-wide strips and Ø32 end bosses. Ø12.10 +0.05/0 end holes at first/last nodes.',f"Trim below local Z=-69. Foot X={c['stop_carrier_foot_x']}, Y=-40..8, Z=-23..-11; holes Ø6.6 +0.10/0 at X={c['stop_carrier_foot_holes_x']}, Y=-36.",f"Right frame global Y={c['stop_carrier_frame_y']-10}; mirror Y for left at {-c['stop_carrier_frame_y']-10}. Two parts; coordinate tolerance ±0.10, pad setting ±0.10° candidate."]+common)
    add(10,'Stop crossbar',[(p['A0-112_stop_crossbar'],'XY','CROSSBAR / AXIAL'),(p['A0-112_stop_crossbar'],'XZ','CROSSBAR / END'),(section(p['A0-112_stop_crossbar'],'YZ'),'YZ','SECTION A–A / X=0')],[f"4140 prehard; Ø{c['stop_bar_od']} center x{c['stop_bar_shoulder_span']} shoulder span; Ø12 -0.02/0 journals x16 each; total{c['stop_bar_span']} ±0.03.", 'Both ends M6x1 x16. Ø5 tap-drill shown. Shoulder span ±0.05; journal coaxiality Ø0.05.', 'Flat normal local Z; offset -8 ±0.03 from axis. 2 x M3x0.5 x6 deep on flat at X=0, Y=±11.', 'Frame journal bores Ø12.10; end washers/M6 bolts positively capture journals. End play/shims and locking inspected.', 'Assemble at computed stop centers, with flat rotated to pad normal.']+common)
    add(11,'Pads and spacers',[(p['A0-107_stop_pad'],'XY','PAD / CONTACT FACE'),(p['A0-107_stop_pad'],'XZ','PAD / SIDE'),(p['A0-205_inner_spacer'],'YZ','SPACER / AXIAL'),(p['A0-203_end_retainer'],'XZ','END WASHER')],[f"Pitch pad {c['stop_pad_size_xyz']} (radial/Y/normal); acetal CANDIDATE, not an energy absorber qualification.",'Ø3.4 through at X=0,Y=±11; Ø6 x2 recess on -Z face. Head Ø5.7 x1.65 sits below contact plane.',f"Spacers Ø21.60 ±0.02 / Ø17.10 +0.05/0; lengths: inner2x4, left {c['outer_spacer_left_length']}, right {c['outer_spacer_right_inner_length']} and {c['outer_spacer_right_outer_length']}; length ±0.02.",'Washer Ø21.6 x3 ±0.02, Ø6.6; key 5x5x30 and 5x5x6. Key width 4.975..5.000 candidate.', 'Measure actual stack; selective shims required. Do not use friction envelope to clamp or locate bearing inner rings.']+common)
    inst={iid:shape for iid,_,shape in instances}
    selected=[v.val() for k,v in inst.items() if k in ('shaft','hub','yoke_1','yoke_2','bearing_1','bearing_2','bearing_cap_1','bearing_cap_2','inner_spacer_1','inner_spacer_2','sector','left_outer_spacer','right_inner_spacer','right_outer_spacer','retainer_1','retainer_2')]
    compound=cq.Compound.makeCompound(selected)
    add(12,'Axial assembly',[(compound,'XY','CARTRIDGE / TOP'),(cq.Workplane('YZ').newObject([compound.translate(tuple(-v for v in design['mechanism']['humeral_stage']['joint_center_mm']))]).section().val(),'YZ','SECTION A–A / THROUGH SHAFT')],['Actual located CAD section; sections include component envelope simplifications. Bearing details/seals are not modeled.',f"SKF 6203-2RSH centers Y=-40,20. Hub Y=-30..10; inner spacers4. Shaft length{c['shaft_length']}.",f"Sector Y={c['sector_center_y']}; friction envelope Y={c['friction_stack_center_y']}. These move outside the foot envelopes.",'Locating cap cavity nominal12.05; floating13.75, allowing inward and outward movement. Worst-case stacks in analysis/A0_R2_INTERFACES.json.', 'Full inner stack is nominal164; select shims from delivered parts. Short stack: annular end shims Ø21.6/17.1. Long stack: shaft-face standoffs Ø16.8/6.6 under end washers. No preload.', 'Assemble cap screws and check inner-ring spacers contact inner rings only.']+common)
    s=design['mechanism']['humeral_stage']['joint_center_mm'];views=[]
    for row in contacts:
        h=inst['hub'].rotate(s,(s[0],s[1]+1,s[2]),row['angle_deg'])
        views.append((cq.Compound.makeCompound([h.val(),inst['pitch_stop_pad_1'].val(),inst['pitch_stop_pad_2'].val(),inst['stop_crossbar_1'].val(),inst['stop_crossbar_2'].val()]),'XZ',f"PITCH {row['angle_deg']}° / TRUE NOMINAL CONTACT"))
    add(13,'Stop contacts',views,[f"Tip circle center R{c['stop_lug_radius']}; reaction normal tangent. Effective arm {contacts[0]['effective_arm_mm']:.3f}."]+[f"θ={r['angle_deg']}° contact from S=({r['contact_from_S_mm'][0]:.5f},0,{r['contact_from_S_mm'][2]:.5f}); bar=({r['backing_center_from_S_mm'][0]:.5f},0,{r['backing_center_from_S_mm'][2]:.5f})." for r in contacts]+['Nominal first contact at -32/+92. At -30/+90 nominal gap ≈2.09.', '4 mm assumed compression would overrun angle limits by ≈3.82°. NO compliance credit; resolve with supplier curve and reviewed stop setting.', 'Acetal compression/creep/rebound and rigid backing/contact verification remain release HOLD.']+common)
    add(14,'Located assembly',[(cq.Compound.makeCompound([shape.val() for _,_,shape in instances]),'XZ','NEUTRAL / FRONT'),(cq.Compound.makeCompound([shape.val() for _,_,shape in instances]),'XY','NEUTRAL / TOP')],[f"{len(parts)} part definitions; {len(instances)} located instances. Purchased hardware includes provisional envelopes.",'Order: fixture/isolation → four-bar/raised carriage → handed yokes → bearing pockets/caps → shaft, spacers, hub/key → sector → end washers/bolts/shims.', 'Fit carrier frames and crossbars, recessed pads, friction/index/tether interfaces, then member to 28 insertion. Inspect all hold points before guarded bench tests.', 'All nominal and sampled checks are bounded digital results. Scapular envelopes, guards, tool access, friction grounding, bench and physical evidence remain open.']+common)
    return result
